$(document).ready(function () {
    // Main category click handler
    $('#main-categories .category-item').click(function () {
        $('#main-categories .category-item').removeClass('active');
        $(this).addClass('active');

        const category = $(this).data('category');
        loadArticles(category);
        updateBadges(category);
    });

    // Badge removal handler
    $(document).on('click', '.remove-badge', function () {
        $('#main-categories .category-item').removeClass('active');
        clearArticles();
        updateBadges();
    });
});

function loadArticles(category) {
    const articles = categoryData[category];
    let html = '';

    articles.forEach(article => {
        html += `
            <a href="${article.url}" class="article-link">
                <i class="fas ${article.icon}"></i>${article.title}
            </a>
        `;
    });

    $('#articles').html(html);
}

function clearArticles() {
    $('#articles').html(`
        <div class="empty-state">
            <i class="fas fa-arrow-left text-muted mb-2"></i>
            <div>Select a category to view guides</div>
        </div>
    `);
}

function updateBadges(category) {
    let badgesHtml = '';

    const activeCategory = category || $('#main-categories .category-item.active').data('category');

    if (activeCategory) {
        const categoryName = $('#main-categories .category-item.active').text().trim();
        badgesHtml += `
            <span class="selection-badge">
                ${categoryName}
                <span class="remove-badge" data-type="category">×</span>
            </span>
        `;
    }

    $('#selected-badges').html(badgesHtml);
}

